public sealed class GridShiftVerification21:MonoBehaviour {
 static bool Requested {get{
#if UNITY_EDITOR
 if(UnityEditor.SessionState.GetBool("GS21Checks",false))return true;
#endif
 return Environment.GetCommandLineArgs().Contains("-gridshift-verify21");}}
 static string DirectoryName{get{var args=Environment.GetCommandLineArgs();int at=Array.IndexOf(args,"-gridshift-report");return at>=0&&at+1<args.Length?args[at+1]:Path.GetFullPath("Docs/Validacao21/runtime");}}
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Install(){if(!Requested)return;GridShiftProfiles.RootOverride=Path.Combine(Application.temporaryCachePath,"GS21-"+Guid.NewGuid().ToString("N"));GridShiftProfiles.Logout();GridShiftCompany.SuppressIntro=true;var go=new GameObject("Version 21 integration verification");Object.DontDestroyOnLoad(go);go.AddComponent<GridShiftVerification21>();}
 StringBuilder report=new StringBuilder();float deadline;bool done;PlayerMovement player;
 void Write(){Directory.CreateDirectory(DirectoryName);File.WriteAllText(Path.Combine(DirectoryName,"runtime.txt"),report.ToString());}
 void Check(bool ok,string text){report.AppendLine((ok?"PASS ":"FAIL ")+text);Write();if(!ok){Finish(false);throw new Exception(text);}}
 void Finish(bool success){if(done)return;done=true;report.AppendLine("RESULT "+(success?"SUCCESS":"FAILURE"));Write();
#if UNITY_EDITOR
 UnityEditor.SessionState.SetBool("GS21Checks",false);UnityEditor.EditorApplication.Exit(success?0:1);
#else
 Application.Quit(success?0:1);
#endif
 }
 void Update(){if(!done&&Time.realtimeSinceStartup>deadline&&deadline>0){report.AppendLine("FAIL timeout scene="+SceneManager.GetActiveScene().name);Finish(false);}}
 TMP_InputField Field(string name)=>Object.FindObjectsByType<TMP_InputField>(FindObjectsSortMode.None).First(f=>f.gameObject.activeInHierarchy&&f.name==name);
 void Button(string title){var button=Object.FindObjectsByType<Button>(FindObjectsSortMode.None).FirstOrDefault(b=>b.isActiveAndEnabled&&b.GetComponentInChildren<TMP_Text>()?.text==title);Check(button!=null,"botão real: "+title);button.onClick.Invoke();}
 IEnumerator Key(Key key){
#if UNITY_EDITOR
InputSystem.settings.editorInputBehaviorInPlayMode=InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;
#endif
if(Keyboard.current==null)InputSystem.AddDevice<Keyboard>();InputSystem.settings.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;Action press=()=>InputState.Change(Keyboard.current,new KeyboardState(key));InputSystem.onAfterUpdate+=press;yield return new WaitForSecondsRealtime(.1f);InputSystem.onAfterUpdate-=press;InputState.Change(Keyboard.current,new KeyboardState());yield return new WaitForSecondsRealtime(.2f);}
 IEnumerator Ready(){while(DeliveryManager.Instance==null||!DeliveryManager.Instance.GetComponent<DeliveryPersistence>().Ready||DeliveryManager.Instance.GetComponent<GridShiftActiveOperations>()?.Van==null||WorldSession.Instance.Busy)yield return null;yield return new WaitForSeconds(.4f);player=InteractionFocus.PlayerFor(DeliveryManager.Instance);}
 void Aim(Vector3 at){var d=Vector3.ProjectOnPlane(at-player.CameraTransform.position,Vector3.up);if(d.sqrMagnitude>.01f)player.transform.rotation=Quaternion.LookRotation(d);player.CameraTransform.LookAt(at);}
 void Place(Vector3 at){player.enabled=false;var cc=player.GetComponent<CharacterController>();cc.enabled=false;player.transform.position=at+Vector3.up*.08f;Physics.SyncTransforms();cc.enabled=true;player.BlockControls(false);}
 IEnumerator Select(GridShiftWorldAction action,Vector3 preferred){for(int i=0;i<8;i++){var at=preferred+Quaternion.Euler(0,i*45,0)*Vector3.forward*.45f;Place(at);yield return null;Aim(action.FocusCollider.bounds.center);yield return null;if(InteractionFocus.Selected(action,player.transform)&&GridShiftDeliveryAccess.InReach(player,action.transform.position,action.range)){yield return Key(GridShiftControls.Binding(GSAction.Interact));yield break;}}Check(false,"alvo deve ser acessível por mira e E: "+action.title);}
 IEnumerator Start(){deadline=Time.realtimeSinceStartup+480;Application.runInBackground=true;yield return new WaitForSecondsRealtime(4);
  Check(!GridShiftProfiles.Login("qualquercoisa","x",out _)&&!GridShiftProfiles.Login("sem@dominio","",out _),"login recusa identificador sem e-mail válido");Button("Novo Jogo");yield return null;Field("E-mail").text="personagem21@exemplo.com";Field("Senha livre (opcional)").text="";Button("Entrar");yield return new WaitForSeconds(.3f);Check(GridShiftProfiles.LoggedIn,"e-mail válido aceita senha vazia");string id=GridShiftProfiles.ProfileId;Check(GridShiftProfiles.Login("PERSONAGEM21@exemplo.com","senha diferente",out _)&&GridShiftProfiles.ProfileId==id,"senha livre e caixa do e-mail preservam o perfil");Field("Nome da empresa").text="Transportes Aurora";
  Button("Criar / editar personagem");yield return new WaitForSeconds(.4f);Check(GridShiftCharacterEditor.IsOpen,"criador abre antes de gravar partida");Field("Nome do personagem").text="Luna Andrade";Field("Idade (1 a 120)").text="27";Field("Cidade de origem (opcional)").text="Belo Horizonte";Field("História e personalidade (opcional)").text="Gosta de conhecer pessoas e organizar entregas.";Button("Próximo visual / roupa");Button("Alternar tom de pele");Button("Alternar cor da roupa");yield return new WaitForSeconds(.3f);Button("Visual e cores");yield return null;Capture("criacao-personagem");for(int gallery=0;gallery<10;gallery++){Button("Próximo visual / roupa");yield return null;Capture("galeria-"+gallery.ToString("00"));}Button("Aplicar personagem");yield return null;var createSlot=Object.FindObjectsByType<Button>(FindObjectsSortMode.None).First(b=>b.isActiveAndEnabled&&b.GetComponentInChildren<TMP_Text>()?.text=="Criar partida"&&b.GetComponentsInParent<RectTransform>().Any(r=>r.name.StartsWith("SLOT 01")));createSlot.onClick.Invoke();yield return Ready();GridShiftOperationsUI.Instance.Close();GridShiftTutorial.Skip();yield return null;
  Check(GridShiftCharacter.Current.name=="Luna Andrade"&&GridShiftCharacter.Current.age==27&&GridShiftCharacter.Current.model==1,"novo jogo restaura identidade e visual definidos na criação");Check(player.transform.Find("Player customized appearance")!=null,"avatar personalizado existe no personagem jogável");var catalog=Resources.Load<GridShiftAvatarCatalog>("GridShiftAvatarCatalog");Check(catalog!=null&&catalog.models.Length==10,"dez visuais preparados estão disponíveis");Check(GridShiftDialogueBank.AuthoredReplyCount>=160,"banco possui pelo menos 160 respostas escritas");int prior=-1;bool repeat=false;for(int i=0;i<60;i++){int chosen;GridShiftDialogueBank.Pick(0,prior,0,out chosen);repeat|=chosen==prior;prior=chosen;}Check(!repeat,"mesma interação evita resposta idêntica consecutiva");
  var npc=Object.FindObjectsByType<GridShiftCitizen>(FindObjectsSortMode.None).First(c=>c.GetComponent<PedestrianAgent>().CurrentActivity!=PedestrianAgent.Activity.Crossing);var interaction=npc.GetComponentsInChildren<GridShiftWorldAction>().First();yield return Select(interaction,npc.transform.position-npc.transform.forward*2f);Check(GridShiftCampaignUI.Instance.SocialOwner==npc,"E abre conversa social presencial");var options=Object.FindObjectsByType<RectTransform>(FindObjectsSortMode.None).First(r=>r.name=="NPC actions bottom right");Check(options.anchorMin==Vector2.right&&options.anchoredPosition.y>0,"opções ficam no canto inferior direito");Button("Cumprimentar");yield return null;Check(Object.FindObjectsByType<TMP_Text>(FindObjectsSortMode.None).Any(t=>t.isActiveAndEnabled&&t.text.Contains("Luna Andrade")),"fala usa nome do personagem do save");Button("Provocar");Button("Insultar");Check(npc.Warmth<0,"provocação e insulto afetam reação do cidadão");Button("Pedir desculpas");yield return null;Capture("conversa-canto-direito");Button("Encerrar conversa");yield return null;Check(!npc.GetComponent<PedestrianAgent>().DialoguePaused&&!player.ControlsBlocked,"encerrar restaura locomoção do NPC e controles");
  var manager=DeliveryManager.Instance;Check(manager.GetComponent<DeliveryPersistence>().Save(),"save preserva ficha do personagem");var read21=GridShiftProfiles.Read(1,out var saved,out _);report.AppendLine("TRACE slot="+GridShiftProfiles.ActiveSlot+" read="+read21+" name="+saved?.character?.name+" origin="+saved?.character?.origin+" path="+GridShiftProfiles.SlotPath(1));File.WriteAllText(Path.Combine(DirectoryName,"capture.json"),JsonUtility.ToJson(manager.GetComponent<DeliveryPersistence>().Capture(),true));Check(read21&&saved.character.name=="Luna Andrade"&&saved.character.origin=="Belo Horizonte","ficha e aparência persistem no slot");Check(GridShiftProfiles.CreateCharacter(2,"Outra empresa",new GridShiftCharacterData{name="Ravi",age=38,model=4},false,out _),"segundo slot recebe personagem próprio");var second=File.ReadAllBytes(GridShiftProfiles.SlotPath(2));GridShiftProfiles.Activate(1,"Transportes Aurora");
  yield return WorldSession.Instance.RequestTransition("Office",player.transform);yield return new WaitForSeconds(.5f);player=InteractionFocus.PlayerFor(manager);var wardrobe=Object.FindFirstObjectByType<GridShiftWardrobe>();Check(wardrobe!=null,"Office instala guarda-roupa físico em área livre");var wardrobeAction=wardrobe.GetComponentInChildren<GridShiftWorldAction>();yield return Select(wardrobeAction,wardrobe.transform.TransformPoint(new Vector3(0,0,1.65f)));report.AppendLine("TRACE wardrobe editor="+GridShiftCharacterEditor.IsOpen+" focus="+InteractionFocus.Selected(wardrobeAction,player.transform)+" reach="+GridShiftDeliveryAccess.InReach(player,wardrobeAction.transform.position,wardrobeAction.range)+" blocked="+player.ControlsBlocked);Check(GridShiftCharacterEditor.IsOpen,"E no guarda-roupa abre personalização");int oldColor=GridShiftCharacter.Current.outfit;Button("Alternar cor da roupa");Button("Próximo visual / roupa");yield return null;Capture("guarda-roupa-office");Button("Aplicar personagem");yield return new WaitForSeconds(.3f);Check(GridShiftCharacter.Current.outfit!=oldColor,"guarda-roupa aplica outra cor de roupa");Check(GridShiftProfiles.Read(1,out saved,out _)&&saved.character.outfit==GridShiftCharacter.Current.outfit,"guarda-roupa grava mudança no save");Check(second.SequenceEqual(File.ReadAllBytes(GridShiftProfiles.SlotPath(2))),"trocar roupa não altera outro slot");
  yield return WorldSession.Instance.RequestTransition("SampleScene",player.transform);yield return new WaitForSeconds(.5f);player=InteractionFocus.PlayerFor(manager);Check(player.transform.Find("Player customized appearance")!=null,"cidade mantém aparência após voltar do Office");Check(Object.FindObjectsByType<AudioListener>(FindObjectsSortMode.None).Count(l=>l.isActiveAndEnabled)==1,"transições mantêm somente um listener");Check(manager.GetComponent<DeliveryPersistence>().Save()&&GridShiftProfiles.Read(1,out saved,out _),"save final disponível para recarregar");int expectedModel=GridShiftCharacter.Current.model,expectedOutfit=GridShiftCharacter.Current.outfit;DeliverySaveStore.Pending=saved;DeliverySaveStore.StartFresh=false;yield return SceneManager.LoadSceneAsync("SampleScene");yield return Ready();Check(GridShiftCharacter.Current.name=="Luna Andrade"&&GridShiftCharacter.Current.model==expectedModel&&GridShiftCharacter.Current.outfit==expectedOutfit,"recarregar partida restaura nome, modelo e roupa");string legacyPath=Path.Combine(GridShiftProfiles.Root,"legacy-characterless.json");string legacyJson=JsonUtility.ToJson(saved).Replace("\"character\":"+JsonUtility.ToJson(saved.character)+",","");File.WriteAllText(legacyPath,legacyJson);bool legacyRead=DeliverySaveStore.ReadAt(legacyPath,out var readLegacy,out _);report.AppendLine("TRACE legacy read="+legacyRead+" character="+(readLegacy?.character!=null)+" key="+legacyJson.Contains("\"character\":"));Check(legacyRead&&readLegacy.character==null,"save v6 sem personagem continua legível");Finish(true);
 }
 void Capture(string name){Directory.CreateDirectory(DirectoryName);var source=Camera.main;if(source==null)source=Object.FindObjectsByType<Camera>(FindObjectsSortMode.None).First(c=>c.isActiveAndEnabled);var overlays=Object.FindObjectsByType<Canvas>(FindObjectsSortMode.None).Where(c=>c.renderMode==RenderMode.ScreenSpaceOverlay).ToArray();var target=new RenderTexture(1920,1080,24);var prior=source.targetTexture;var active=RenderTexture.active;foreach(var c in overlays){c.renderMode=RenderMode.ScreenSpaceCamera;c.worldCamera=source;c.planeDistance=.8f;}source.targetTexture=target;Canvas.ForceUpdateCanvases();source.Render();RenderTexture.active=target;var image=new Texture2D(1920,1080,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1920,1080),0,0);image.Apply();File.WriteAllBytes(Path.Combine(DirectoryName,name+".png"),image.EncodeToPNG());source.targetTexture=prior;RenderTexture.active=active;foreach(var c in overlays){c.renderMode=RenderMode.ScreenSpaceOverlay;c.worldCamera=null;}target.Release();Object.Destroy(target);Object.Destroy(image);}
}







